## Why This Is Asked

This question evaluates full-stack frontend capabilities by testing multiple advanced concepts in a single feature: DOM diffing algorithms, network resilience patterns, offline-first architecture, request optimization, and cross-browser tab synchronization.

## Key Concepts

- Patch-based DOM updates for efficient rendering
- WebSocket reconnection with exponential backoff strategy
- Service Worker for intelligent caching and payload storage
- In-flight request deduplication for performance optimization
- BroadcastChannel API for cross-tab state synchronization

## Code Example

```javascript
// API Sketch
GET /api/widgets          // Initial widget data
WS /api/realtime          // WebSocket endpoint

// Fetch wrapper with deduplication and caching
const fetchCache = new Map();
const pendingRequests = new Map();

const smartFetch = async (url, options = {}) => {
  const cacheKey = `${url}:${JSON.stringify(options)}`;
  const cached = fetchCache.get(cacheKey);

  if (cached && Date.now() - cached.timestamp < 60000) {
    return cached.data;
  }

  if (pendingRequests.has(cacheKey)) {
    return pendingRequests.get(cacheKey);
  }

  const promise = fetch(url, options).then(response => response.json());
  pendingRequests.set(cacheKey, promise);

  try {
    const data = await promise;
    fetchCache.set(cacheKey, { data, timestamp: Date.now() });
    return data;
  } finally {
    pendingRequests.delete(cacheKey);
  }
};

// WebSocket with exponential backoff
const connectWebSocket = (url, maxRetries = 5) => {
  let retryCount = 0;

  const connect = () => {
    const ws = new WebSocket(url);

    ws.onopen = () => {
      retryCount = 0;
      console.log('WebSocket connected');
    };

    ws.onclose = () => {
      if (retryCount < maxRetries) {
        const delay = Math.min(1000 * Math.pow(2, retryCount), 30000);
        setTimeout(connect, delay);
        retryCount++;
      }
    };

    return ws;
  };

  return connect();
};

// Cross-tab state synchronization
const broadcast = new BroadcastChannel('dashboard-state');

broadcast.onmessage = (event) => {
  if (event.data.type === 'widget-update') {
    updateWidget(event.data.payload);
  }
};

// DOM patch updater
const updateWidget = (changes) => {
  const widget = document.getElementById(changes.widgetId);
  if (!widget) return;

  // Simple patch-based update
  changes.patches.forEach(patch => {
    const element = widget.querySelector(patch.selector);
    if (element) {
      if (patch.type === 'text') {
        element.textContent = patch.value;
      } else if (patch.type === 'attr') {
        element.setAttribute(patch.name, patch.value);
      }
    }
  });
};
```

## Why This Is Asked

This question tests mastery of closures, promises, and per-key caching with real-world constraints like deduplicating in-flight requests, enforcing concurrency limits, and implementing TTL-based invalidation.

## Key Concepts

- **Closures and per-key cache state**: Using closures to maintain cache and in-flight maps private to each loader instance
- **In-flight deduplication**: Sharing promises for concurrent requests to the same key to prevent redundant fetches
- **Concurrency control**: Implementing a semaphore pattern with a 3-request cap
- **TTL-based caching**: Storing expiration timestamps and evicting stale entries
- **Background refresh**: Silently refetching expired keys without blocking callers
- **Invalidation semantics**: Manual cache invalidation for real-time scenarios

## Code Example

```javascript
function createResourceLoader(fetcher) {
  const cache = new Map();
  const inFlight = new Map();
  let active = 0;
  const maxConcurrent = 3;
  const waiting = [];

  const acquire = () => new Promise(resolve => {
    if (active < maxConcurrent) {
      active++;
      resolve();
    } else {
      waiting.push(resolve);
    }
  });

  const release = () => {
    if (waiting.length > 0) {
      waiting.shift()();
    } else {
      active--;
    }
  };

  return {
    load(key, ttl = 5000) {
      const cached = cache.get(key);
      const now = Date.now();

      if (cached) {
        if (cached.expiry > now) {
          return cached.value;
        }
        if (!inFlight.has(key)) {
          fetcher(key).then(value => {
            cache.set(key, { value, expiry: Date.now() + ttl });
          });
        }
      }

      if (inFlight.has(key)) {
        return inFlight.get(key);
      }

      const promise = acquire().then(async () => {
        try {
          const value = await fetcher(key);
          cache.set(key, { value, expiry: Date.now() + ttl });
          return value;
        } finally {
          release();
          inFlight.delete(key);
        }
      });

      inFlight.set(key, promise);
      return promise;
    },

    invalidate(key) {
      cache.delete(key);
    }
  };
}

// Mock fetcher
const fetchUser = createResourceLoader(async (id) => {
  console.log(`Fetching user ${id}...`);
  await new Promise(r => setTimeout(r, 100));
  return { id, name: `User ${id}` };
});

// Usage
await fetchUser.load('user:1', 2000);
await fetchUser.load('user:1'); // Uses cache
fetchUser.invalidate('user:1');
await fetchUser.load('user:1'); // Refetches
```

